<?php $root='../../';require '../../includes/header.php';$mes=$_GET['mes']??date('Y-m');$s=$pdo->prepare('SELECT b.documento,b.nombre,b.ficha,s.asistencia,s.entrega_documentos,s.fic,s.novedad,s.resultado,s.observaciones FROM seguimientos s JOIN beneficiarios b ON b.id=s.beneficiario_id WHERE s.mes=? ORDER BY b.nombre');$s->execute([$mes]);$rows=$s->fetchAll();if(isset($_GET['csv'])){while(ob_get_level())ob_end_clean();header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename=reporte_'.$mes.'.csv');$o=fopen('php://output','w');fputcsv($o,['Documento','Nombre','Ficha','Asistencia','Documentos','FIC','Novedad','Resultado','Observaciones']);foreach($rows as $r)fputcsv($o,$r);exit;}?><div class="d-flex justify-content-between"><h2>Reportes</h2><form class="d-flex gap-2"><input type="month" name="mes" value="<?=$mes?>" class="form-control"><button class="btn btn-primary">Consultar</button><a class="btn btn-success" href="?mes=<?=$mes?>&csv=1">Exportar CSV</a></form></div><div class="card p-3 mt-3 table-responsive"><table class="table"><thead><tr><th>Documento</th><th>Nombre</th><th>Ficha</th><th>FIC</th><th>Resultado</th><th>Novedad</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['documento']?></td><td><?=htmlspecialchars($r['nombre'])?></td><td><?=$r['ficha']?></td><td><?=$r['fic']?></td><td><?=$r['resultado']?></td><td><?=htmlspecialchars($r['novedad']??'')?></td></tr><?php endforeach?></tbody></table></div><?php require '../../includes/footer.php';?>